### The Lab, the Lab Substation and the Power Plant (Asciiverse, 2026)
#
# After Whales' notes (docs/notes.txt): the Lab sits at the centre of the
# island; it opens when the Power Plant runs, its Substation passes the
# power on, and a passcard is shown at the blast door.  The panels, the door
# and the core are worked by examining them (escape.cpp, lab.cpp).

name: std_lab_asciiverse
type: lab
base_terrain: concrete floor
tile: , = pavement
tile: # = stone wall
tile: . = floor
tile: D = lab blast door
tile: C = lab core
tile: r = server rack
tile: m = machinery
tile: ' = closed door
tile: " = bulletproof glass
items: 30 . = w:3 first aid kit / w:3 bandages / w:2 batteries / w:1 flashlight / w:2 data cable / w:2 processor
items: 60 r = w:3 processor / w:3 RAM / w:3 data cable
map:
,,,,,,,,,,,,,,,,,,,,,,,,,
,#######################,
,#rrrr...........rrrr..#,
,#.......mmmmm.........#,
,#.......mCCCm.........#,
,#.......mm.mm.........#,
,#.....................#,
,####"####'''####"######,
,#.....#.........#.....#,
,#.r...#.........#...r.#,
,#.r...'.........'...r.#,
,#.....#.........#.....#,
,####'###.......###'####,
,#.......#.....#.......#,
,#.......#.....#.......#,
,#..m....'.....'....m..#,
,#.......#.....#.......#,
,#########.....#########,
,#.....................#,
,#.....................#,
,#####################D#,
,,,,,,,,,,,,,,,,,,,,,,,,,
,,,,,,,,,,,,,,,,,,,,,,,,,
,,,,,,,,,,,,,,,,,,,,,,,,,
,,,,,,,,,,,,,,,,,,,,,,,,,
endmap
done

